#!/bin/sh
# births of the census's 720 at each tree, 3 at a time
for t in a-tip ab-base b-tip; do mkdir -p /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t; ( TREE=/tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/$t OUT=/tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t node /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/births.mjs > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t.log 2>&1; echo "EXIT $?" >> /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t.log ) & done; wait
for t in c-tip c-base; do mkdir -p /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t; ( TREE=/tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/$t OUT=/tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t node /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/births.mjs > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t.log 2>&1; echo "EXIT $?" >> /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/b720/$t.log ) & done; wait
echo BIRTHS-DONE $(date -u +%T)
